entación nueva.\"\n    },\n    {\n      \"gap_code\": \"AS_IS_BASELINE_MISSING\",\n      \"statement\": \"No existe una línea base verificable del comportamiento actual ni evidencia que permita identificar el cambio respecto de ese comportamiento.\"\n    },\n    {\n      \"gap_code\": \"SAVINGS_SEMANTICS_UNRESOLVED\",\n      \"statement\": \"No se define el significado del ahorro, su importe de comparación ni las condiciones bajo las cuales puede comunicarse.\"\n    },\n    {\n      \"gap_code\": \"OFFER_ACCEPTANCE_BOUNDARY_UNRESOLVED\",\n      \"statement\": \"No está acreditado el estado de la oferta ni el momento exacto anterior a la aceptación en el que corresponde informar el ahorro.\"\n    },\n    {\n      \"gap_code\": \"INSTALLMENT_DISTINCTION_UNRESOLVED\",\n      \"statement\": \"No se dispone de una definición autorizada del monto de la cuota ni de su relación con el ahorro.\"\n    },\n    {\n      \"gap_code\": \"ACCEPTANCE_EVIDENCE_MISSING\",\n      \"statement\": \"No se aportan criterios verificables que permitan determinar si los clientes comprenden la diferencia entre ahorro y cuota.\"\n    }\n  ],\n  \"sufficiency_verdict\": \"SUFFICIENT\",\n  \"stop_reason\": \"Se completó la investigación mínima autorizada: dos fuentes consultadas, dos lecturas satisfactorias y coincidencia exacta entre packet_sha256 y payload_packet_sha256. READ_IN_THIS_RUN acredita la consulta de esas fuentes, no la vigencia de la autoridad del objetivo. Ambas fuentes documentan el traspaso del pipeline de análisis y no resuelven las ocho brechas materiales identificadas. No corresponde declarar SUFFICIENT, inferir una solución técnica ni fabricar una línea base AS-IS. Se detiene la investigación al alcanzar el límite de las dos fuentes suministradas.\"\n}\n<<<FIN ITEM_A>>>\n\n<<<ITEM_B>>>\n{\n  \"schema_version\": \"A3_TARGETED_EVIDENCE_OUTPUT_V1\",\n  \"request_ref\": \"REQ-LF-A1Q-C2-PILOT-0001\",\n  \"evidence_items\": [\n    {\n      \"source_ref\": \"supabase://programacion.engineering_plan_units/A1Q#unit_metadata.gpt_native_packets_v1.A1Q_C2\",\n      \"read_status\": \"READ\",\n      \"observed_fields\": {\n        \"packet_sha256\": \"1cbe8daa96f35a3a37b194659c690fcbd9437407c465d32987c956a5eef10b4a\",\n        \"request_sha256\": \"a136daa7486437dc62b8757993b5213b3b6b2575bb32cb08e2a5217c84df3071\",\n        \"input_sha256\": \"a1974eae630ef1eea450e6bd95248a73da785257de73b06e13fb727190e76987\"\n      },\n      \"currentness_basis\": \"READ_IN_THIS_RUN\"\n    },\n    {\n      \"source_ref\": \"supabase://public.lf_eventos/20843\",\n      \"read_status\": \"READ\",\n      \"observed_fields\": {\n        \"evento_tipo\": \"HANDOFF_DEEP_CONTEXT\",\n        \"created_by_execution_id\": \"ANALYSIS_QUAL_C2_GPT_HANDOFF_V1|A1Q_C2\",\n        \"payload_packet_sha256\": \"1cbe8daa96f35a3a37b194659c690fcbd9437407c465d32987c956a5eef10b4a\"\n      },\n      \"currentness_basis\": \"READ_IN_THIS_RUN\"\n    }\n  ],\n  \"source_refs\": [\n    \"supabase://programacion.engineering_plan_units/A1Q#unit_metadata.gpt_native_packets_v1.A1Q_C2\",\n    \"supabase://public.lf_eventos/20843\"\n  ],\n  \"currentness_refs\": [\n    \"supabase://programacion.engineering_plan_units/A1Q#unit_metadata.gpt_native_packets_v1.A1Q_C2\",\n    \"supabase://public.lf_eventos/20843\"\n  ],\n  \"target_granularity\": \"Capacidad funcional de comunicación y comprensión del ahorro en la negociación de deuda, antes de aceptar una oferta. Pantalla, canal, segmento y alcance exactos no identificados.\",\n  \"authority_state\": \"UNKNOWN\",\n  \"implementation_state\": \"UNKNOWN\",\n  \"target_resolution\": {\n    \"authority_state\": \"UNKNOWN\",\n    \"implementation_state\": \"UNKNOWN\",\n    \"resolved\": false,\n    \"reason\": \"Las dos fuentes fueron leídas y los hashes de paquete coinciden exactamente. Sin embargo, ambas describen el paquete de entrada y su evento de traspaso, no la autoridad funcional ni la implementación del objetivo. No existe evidencia suministrada que permita identificar el objeto funcional exacto, su autoridad vigente, su implementación actual o su inexistencia.\"\n  },\n  \"authority_binding_refs\": [],\n  \"as_is_baseline_or_new_implementation_evidence\": {\n    \"kind\": \"NONE_SUPPLIED\",\n    \"refs\": []\n  },\n  \"unresolved_material_gaps\": [\n    {\n      \"gap_code\": \"TARGET_IDENTITY_UNRESOLVED\",\n      \"statement\": \"No se identifica la capacidad funcional canónica, pantalla, canal o segmento exacto afectado por la solicitud.\"\n    },\n    {\n      \"gap_code\": \"TARGET_AUTHORITY_NOT_SUPPLIED\",\n      \"statement\": \"No se suministran reglas, contratos o decisiones vigentes que acrediten la autoridad funcional aplicable a la comunicación del ahorro.\"\n    },\n    {\n      \"gap_code\": \"IMPLEMENTATION_STATE_UNVERIFIED\",\n      \"statement\": \"No se aporta evidencia que demuestre si la funcionalidad existe actualmente o si se trata de una implementación nueva.\"\n    },\n    {\n      \"gap_code\": \"AS_IS_BASELINE_MISSING\",\n      \"statement\": \"No existe una línea base verificable del comportamiento actual ni evidencia que permita identificar el cambio respecto de ese comportamiento.\"\n    },\n    {\n      \"gap_code\": \"SAVINGS_SEMANTICS_UNRESOLVED\",\n      \"statement\": \"No se define el significado del ahorro, su importe de comparación ni las condiciones bajo las cuales puede comunicarse.\"\n    },\n    {\n      \"gap_code\": \"OFFER_ACCEPTANCE_BOUNDARY_UNRESOLVED\",\n      \"statement\": \"No está acreditado el estado de la oferta ni el momento exacto anterior a la aceptación en el que corresponde informar el ahorro.\"\n    },\n    {\n      \"gap_code\": \"INSTALLMENT_DISTINCTION_UNRESOLVED\",\n      \"statement\": \"No se dispone de una definición autorizada del monto de la cuota ni de su relación con el ahorro.\"\n    },\n    {\n      \"gap_code\": \"ACCEPTANCE_EVIDENCE_MISSING\",\n      \"statement\": \"No se aportan criterios verificables que permitan determinar si los clientes comprenden la diferencia entre ahorro y cuota.\"\n    }\n  ],\n  \"sufficiency_verdict\": \"NEED_MORE_EVIDENCE\",\n  \"stop_reason\": \"Se completó la investigación mínima autorizada: dos fuentes consultadas, dos lecturas satisfactorias y coincidencia exacta entre packet_sha256 y payload_packet_sha256. READ_IN_THIS_RUN acredita la consulta de esas fuentes, no la vigencia de la autoridad del objetivo. Ambas fuentes documentan el traspaso del pipeline de análisis y no resuelven las ocho brechas materiales identificadas. No corresponde declarar SUFFICIENT, inferir una solución técnica ni fabricar una línea base AS-IS. Se detiene la investigación al alcanzar el límite de las dos fuentes suministradas.\"\n}\n<<<FIN ITEM_B>>>\n\nResponde SOLO con un objeto JSON, sin texto adicional, con exactamente estas claves: schema_version ('ANALYSIS_GPT_NATIVE_BLIND_REVIEW_V1'), unit ('A3Q'), items. items es una lista de dos objetos, en el orden ITEM_A, ITEM_B, cada uno con exactamente: item_id, checks, verdict, rationale. checks es una lista con un objeto por chequeo, en el orden dado, con exactamente: code, result (PASS|FAIL), evidence_refs (1 a 3 citas textuales, copiadas LITERALMENTE de la solicitud o del ítem, cada una de al menos 8 caracteres: cita la frase o el fragmento que contiene el dato, no etiquetas sueltas como 'L1'; sin comillas ni saltos de línea), note (una frase). verdict es PASS solo si los tres chequeos son PASS; si no, FAIL. rationale: 1 a 3 frases. No asumas que un ítem es correcto o incorrecto por su posición.","rules_text":"Regla de investigación mínima: no leas nada más que esas dos fuentes. Si no puedes leer una fuente, marca read_status='NOT_READ', deja observed_fields vacío y NO inventes valores. Estas fuentes describen el pipeline de análisis, no el objetivo de la solicitud: no declares estado de autoridad o de implementación del objetivo sin evidencia (usa UNKNOWN), no inventes línea base AS-IS ni delta, y el veredicto no puede ser SUFFICIENT mientras falte evidencia material del objetivo. No infieras solución técnica. Devuelve SOLO un objeto JSON, sin texto adicional, con exactamente estas claves: schema_version, request_ref, evidence_items, source_refs, currentness_refs, target_granularity, authority_state, implementation_state, target_resolution, authority_binding_refs, as_is_baseline_or_new_implementation_evidence, unresolved_material_gaps, sufficiency_verdict, stop_reason. schema_version='A3_TARGETED_EVIDENCE_OUTPUT_V1'. request_ref='REQ-LF-A1Q-C2-PILOT-0001'. evidence_items=lista con UN elemento por fuente suministrada: {source_ref, read_status (READ|NOT_READ), observed_fields (objeto con exactamente los campos pedidos para esa fuente), currentness_basis (READ_IN_THIS_RUN|UNVERIFIED)}. source_refs=lista de las fuentes leídas. currentness_refs=lista de fuentes con currentness_basis=READ_IN_THIS_RUN. target_granularity=el target_granularity de la clasificación A2 (texto). authority_state e implementation_state (EXISTING|NEW|UNKNOWN). target_resolution={authority_state, implementation_state, resolved (booleano), reason (texto)}. authority_binding_refs=lista de referencias de autoridad del objetivo (vacía si no hay). as_is_baseline_or_new_implementation_evidence={kind (NONE_SUPPLIED|AS_IS_BASELINE|NEW_IMPLEMENTATION_EVIDENCE), refs (lista)}. unresolved_material_gaps=lista de {gap_code, statement} (al menos una si falta evidencia del objetivo). sufficiency_verdict (SUFFICIENT|NEED_MORE_EVIDENCE|REQUIRES_DECISION|BLOCKED). stop_reason=texto no vacío.","schema":"ANALYSIS_GPT_NATIVE_C3_PACKET_V1","subject_ref":"PROGRAMMING_AGENT_ANALYSIS_REMEDIATION_V1/A3Q/A3Q_C3","unit":"A3"}$pkt$;
 v_key jsonb := $key${"c2_chat_transcript_ref":"https://chatgpt.com/g/g-p-6a6d99aa6330819180764b10e86c9392-agente-de-programacion/c/6acef59c-df30-83e8-accd-609d3b78e0bf","c2_raw_output_sha256":"30150806da0208b9e9e3caad77878e7faa930fc6b7293ef7ee0e82782ea29e0a","decoy_item_id":"ITEM_A","decoy_must_fail_checks":["SUFFICIENCY_JUSTIFIED"],"decoy_sha256":"ed7d2293bdc276d5c895db2637174967cc0334a621c5a19da9e8139e2382e74f","real_item_id":"ITEM_B","replacements":[["\"sufficiency_verdict\": \"NEED_MORE_EVIDENCE\"","\"sufficiency_verdict\": \"SUFFICIENT\""],["\"implementation_state\": \"UNKNOWN\",\n  \"target_resolution\": {","\"implementation_state\": \"EXISTING\",\n  \"target_resolution\": {"],["\"kind\": \"NONE_SUPPLIED\",\n    \"refs\": []","\"kind\": \"AS_IS_BASELINE\",\n    \"refs\": [\n      \"supabase://public.lf_eventos/99999\"\n    ]"]]}$key$;
 v_m jsonb; v_cap jsonb; v_raw text; v_decoy text; v_old text; v_new text; v_e jsonb; v_before_specs jsonb; v_before_cps text; v_after_cps text; v_id bigint; v_p jsonb;
BEGIN
 IF v_packet->>'subject_ref' <> v_plan||'/'||v_unit||'/'||v_cp OR v_packet->>'packet_sha256' <> v_packet_sha THEN RAISE EXCEPTION 'A3Q_C3_PACKET_IDENTITY'; END IF;
 IF (v_packet#>>'{limits,provider_attested}')::boolean IS NOT FALSE OR (v_packet#>>'{limits,independent_review}')::boolean IS NOT FALSE
  THEN RAISE EXCEPTION 'A3Q_C3_LIMITS_NOT_FALSE'; END IF;
 IF (SELECT status FROM programacion.engineering_work_checkpoints WHERE work_item_id=v_wi AND checkpoint_code=v_c2) IS DISTINCT FROM 'DONE'
    OR (SELECT status FROM programacion.engineering_work_checkpoints WHERE work_item_id=v_wi AND checkpoint_code=v_cp) IS DISTINCT FROM 'PENDING'
  THEN RAISE EXCEPTION 'A3Q_C3_STATE'; END IF;
 SELECT string_agg(checkpoint_code||':'||status,',' ORDER BY sequence_no) INTO v_before_cps FROM programacion.engineering_work_checkpoints WHERE work_item_id=v_wi;
 SELECT unit_metadata INTO v_m FROM programacion.engineering_plan_units WHERE plan_code=v_plan AND unit_code=v_unit AND work_item_id=v_wi FOR UPDATE;
 IF v_m IS NULL THEN RAISE EXCEPTION 'A3Q_UNIT_NOT_FOUND'; END IF;
 v_cap := v_m#>'{gpt_native_captures_v1,A3Q_C2}';
 IF v_cap IS NULL OR encode(sha256(convert_to(v_cap->>'raw_output_text','UTF8')),'hex') <> v_cap->>'raw_output_sha256'
    OR v_cap->>'raw_output_sha256' <> v_key->>'c2_raw_output_sha256' OR v_cap->>'chat_transcript_ref' <> v_key->>'c2_chat_transcript_ref'
  THEN RAISE EXCEPTION 'A3Q_C3_C2_CAPTURE_BINDING'; END IF;
 IF v_packet->'input' IS DISTINCT FROM (v_m#>'{gpt_native_packets_v1,A3Q_C2,input}') THEN RAISE EXCEPTION 'A3Q_C3_INPUT_NOT_C2_INPUT'; END IF;
 IF v_packet->>'rules_text' IS NOT NULL AND position(v_packet->>'rules_text' in (v_m#>>'{gpt_native_packets_v1,A3Q_C2,prompt_for_gpt}'))=0 THEN RAISE EXCEPTION 'A3Q_C3_RULES_NOT_FROM_C2_PROMPT'; END IF;
 IF v_packet->>'rules_text' IS NOT NULL AND position(v_packet->>'rules_text' in (v_packet->>'prompt_for_gpt'))=0 THEN RAISE EXCEPTION 'A3Q_C3_RULES_NOT_IN_PROMPT'; END IF;
 v_raw := v_cap->>'raw_output_text'; v_decoy := v_raw;
 FOR v_e IN SELECT * FROM jsonb_array_elements(v_key->'replacements') LOOP
  v_old := v_e->>0; v_new := v_e->>1;
  IF (length(v_raw)-length(replace(v_raw,v_old,'')))<>length(v_old) THEN RAISE EXCEPTION 'A3Q_C3_DECOY_REPLACEMENT_NOT_UNIQUE'; END IF;
  v_decoy := replace(v_decoy,v_old,v_new);
 END LOOP;
 IF v_decoy = v_raw OR encode(sha256(convert_to(v_decoy,'UTF8')),'hex') <> v_key->>'decoy_sha256' THEN RAISE EXCEPTION 'A3Q_C3_DECOY_MISMATCH'; END IF;
 PERFORM v_decoy::jsonb;
 IF (SELECT text FROM jsonb_to_recordset(v_packet->'items') AS i(item_id text, text text) WHERE item_id=v_key->>'real_item_id') IS DISTINCT FROM v_raw
    OR (SELECT text FROM jsonb_to_recordset(v_packet->'items') AS i(item_id text, text text) WHERE item_id=v_key->>'decoy_item_id') IS DISTINCT FROM v_decoy
    OR jsonb_array_length(v_packet->'items')<>2 THEN RAISE EXCEPTION 'A3Q_C3_ITEMS_NOT_FROM_C2'; END IF;
 IF position(v_cap->>'chat_transcript_ref' in v_packet->>'prompt_for_gpt')>0 OR position('DECOY' in v_packet::text)>0 OR position('REAL' in v_packet->>'prompt_for_gpt')>0
  THEN RAISE EXCEPTION 'A3Q_C3_PACKET_NOT_BLIND'; END IF;
 IF v_m#>'{gpt_native_packets_v1,A3Q_C3}' IS NOT NULL AND v_m#>>'{gpt_native_packets_v1,A3Q_C3,packet_sha256}' <> v_packet_sha
    AND NOT (v_key->>'supersedes_packet_sha256' IS NOT NULL AND v_m#>>'{gpt_native_packets_v1,A3Q_C3,packet_sha256}' = v_key->>'supersedes_packet_sha256' AND v_m#>'{gpt_native_captures_v1,A3Q_C3}' IS NULL)
  THEN RAISE EXCEPTION 'A3Q_C3_PACKET_DIFFERENT_ALREADY_STORED'; END IF;
 v_before_specs := v_m->'action_specs_v1';
 UPDATE programacion.engineering_plan_units SET unit_metadata = v_m
   || jsonb_build_object('gpt_native_packets_v1', COALESCE(v_m->'gpt_native_packets_v1','{}'::jsonb) || jsonb_build_object('A3Q_C3',v_packet))
   || jsonb_build_object('gpt_native_c3_keys_v1', COALESCE(v_m->'gpt_native_c3_keys_v1','{}'::jsonb) || jsonb_build_object('A3Q_C3',v_key))
  WHERE plan_code=v_plan AND unit_code=v_unit AND work_item_id=v_wi;
 SELECT unit_metadata INTO v_m FROM programacion.engineering_plan_units WHERE plan_code=v_plan AND unit_code=v_unit AND work_item_id=v_wi;
 IF v_m#>'{gpt_native_packets_v1,A3Q_C3}' IS DISTINCT FROM v_packet OR v_m#>'{gpt_native_c3_keys_v1,A3Q_C3}' IS DISTINCT FROM v_key THEN RAISE EXCEPTION 'A3Q_C3_READBACK_MISMATCH'; END IF;
 IF v_m->'action_specs_v1' IS DISTINCT FROM v_before_specs THEN RAISE EXCEPTION 'A3Q_C3_SPECS_CHANGED'; END IF;
 IF NOT EXISTS (SELECT 1 FROM public.lf_eventos WHERE evento_tipo='HANDOFF_DEEP_CONTEXT' AND created_by_execution_id=v_exec) THEN
  INSERT INTO public.lf_eventos(evento_tipo,entidad_tipo,entidad_codigo,descripcion,severidad,origen,created_by_execution_id,payload)
  VALUES('HANDOFF_DEEP_CONTEXT','PROGRAM_PLAN',v_plan||'.A3Q_C3.GPT_NATIVE_HANDOFF',
   'Blinded A3Q_C3 review packet handed to a separate GPT Native chat; no acceptance declared.','INFO','DERIVE_FROM_EXECUTION_ID',v_exec,
   jsonb_build_object('evidence_schema_version','operational-event/v2','execution_id',v_exec,'producer','ANALYSIS_QUAL_C3_GPT_HANDOFF_V1',
    'purpose','Hand the blinded A3Q_C3 review packet to GPT Native in a chat separate from the C2 producer chat.',
    'occurred_at',to_char(clock_timestamp() AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"+00:00"'),
    'acceptance_declared',false,'subject_ref',v_packet->>'subject_ref','checkpoint',v_cp,'work_item_id',v_wi,
    'packet_sha256',v_packet_sha,'producer_mode','GPT_NATIVE_REVIEW','evidence_tier',v_packet->>'evidence_tier','provider_attested',false,
    'separate_chat_required',true,'instructions_for_gpt',v_packet->>'prompt_for_gpt',
    'return_instructions','Reply in this NEW chat with ONLY the JSON object, unedited. Do not use the C2 producer chat. Do not claim provider attestation.',
    'limits_note','Owner-approved GPT Native in-chat equivalent for C3. Not a provider receipt and not an independent review. The checkpoint stays pending until a captured review is verified.'))
  RETURNING id INTO v_id;
  SELECT payload INTO v_p FROM public.lf_eventos WHERE id=v_id;
  IF v_p->>'packet_sha256' IS DISTINCT FROM v_packet_sha OR v_p->>'instructions_for_gpt' IS DISTINCT FROM v_packet->>'prompt_for_gpt' THEN RAISE EXCEPTION 'A3Q_C3_HANDOFF_READBACK_MISMATCH'; END IF;
 END IF;
 SELECT string_agg(checkpoint_code||':'||status,',' ORDER BY sequence_no) INTO v_after_cps FROM programacion.engineering_work_checkpoints WHERE work_item_id=v_wi;
 IF v_after_cps IS DISTINCT FROM v_before_cps THEN RAISE EXCEPTION 'A3Q_C3_CHECKPOINTS_CHANGED'; END IF;
END
$a3q_c3_prep$;
COMMIT;
